using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Shared;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments.Select(s => new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail,
            Notes = s.Notes
        }).ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var s = await db.Shipments.FindAsync(id);
        if (s is null) return null;
        return new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail,
            Notes = s.Notes
        };
    }

    public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
    {
        var s = await db.Shipments.FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
        if (s is null) return null;
        return new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail,
            Notes = s.Notes
        };
    }

    public async Task<bool> UpdateStatusAsync(int id, ShipmentStatusUpdate update)
    {
        var s = await db.Shipments.FindAsync(id);
        if (s is null) return false;
        s.Status = update.Status;
        if (update.EstimatedDelivery.HasValue)
            s.EstimatedDelivery = update.EstimatedDelivery.Value;
        if (update.Notes is not null)
            s.Notes = update.Notes;
        await db.SaveChangesAsync();
        return true;
    }
}

using System.Net.Http.Json;
using ShipmentTracker.Shared;

namespace ShipmentTracker.Client.Services;

public class ShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
