@page "/dispatcher"
@using ShipmentTracker.Shared
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentSvc
@rendermode InteractiveAuto

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Shipment Dashboard</h2>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
                    <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                    <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        <button class="btn btn-sm btn-primary" @onclick="() => OpenUpdateModal(s)">Update</button>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (selectedShipment is not null)
    {
        <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Update @selectedShipment.TrackingNumber</h5>
                        <button type="button" class="btn-close" @onclick="CloseModal"></button>
                    </div>
                    <div class="modal-body">
                        <div class="mb-3">
                            <label class="form-label">Status</label>
                            <select class="form-select" @bind="newStatus">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Estimated Delivery</label>
                            <input type="date" class="form-control" @bind="newEstimatedDelivery" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Notes</label>
                            <textarea class="form-control" @bind="newNotes"></textarea>
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CloseModal">Cancel</button>
                        <button class="btn btn-success" @onclick="SaveStatus">Save</button>
                    </div>
                </div>
            </div>
        </div>
    }
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private ShipmentDto? selectedShipment;
    private ShipmentStatus newStatus;
    private DateTime newEstimatedDelivery;
    private string? newNotes;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments!.Where(s => string.IsNullOrEmpty(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentSvc.GetAllShipmentsAsync();
    }

    private void OpenUpdateModal(ShipmentDto s)
    {
        selectedShipment = s;
        newStatus = s.Status;
        newEstimatedDelivery = s.EstimatedDelivery;
        newNotes = s.Notes;
    }

    private void CloseModal() => selectedShipment = null;

    private async Task SaveStatus()
    {
        if (selectedShipment is null) return;
        var update = new ShipmentStatusUpdate
        {
            Status = newStatus,
            EstimatedDelivery = newEstimatedDelivery,
            Notes = newNotes
        };
        var success = await ShipmentSvc.UpdateStatusAsync(selectedShipment.Id, update);
        if (success)
        {
            selectedShipment.Status = newStatus;
            selectedShipment.EstimatedDelivery = newEstimatedDelivery;
            selectedShipment.Notes = newNotes;
        }
        CloseModal();
    }

    private string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

@page "/track"
@using ShipmentTracker.Shared
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentSvc
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-1001)" @bind="trackingNumber" @onkeyup="HandleKeyUp" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @if (isSearching) { <span class="spinner-border spinner-border-sm"></span> }
                else { <span>Search</span> }
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge bg-@GetStatusColor(shipment.Status) ms-2">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>Origin:</strong> @shipment.Origin</p>
                    <p><strong>Destination:</strong> @shipment.Destination</p>
                    <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    @if (shipment.Notes is not null)
                    {
                        <p><strong>Notes:</strong> @shipment.Notes</p>
                    }
                </div>
            </div>

            <h5 class="mt-3">Delivery Progress</h5>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar bg-@GetStatusColor(shipment.Status)" role="progressbar"
                     style="width: @(GetProgress(shipment.Status))%"
                     aria-valuenow="@GetProgress(shipment.Status)" aria-valuemin="0" aria-valuemax="100">
                    @shipment.Status
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isSearching;

    private async Task HandleKeyUp(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isSearching = true;
        errorMessage = null;
        shipment = null;

        shipment = await ShipmentSvc.TrackShipmentAsync(trackingNumber.Trim());
        if (shipment is null)
            errorMessage = $"No shipment found with tracking number '{trackingNumber}'.";

        isSearching = false;
    }

    private int GetProgress(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        _ => 0
    };

    private string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

